#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# ── storewarden smoke-test helpers ────────────────────────────────────────
#
# Everything happens in a personal tailnet. storewarden and the two test
# Callers (cmd/storewarden-smoke) are tsnet nodes that join whichever tailnet
# issued their auth keys, so the Tailscale app on this machine, and the
# tailnet it's logged into, are never used. The app's tailnet name is read
# only to refuse to run in it.
#
# Part 1 (stages 9-13) checks the tailnet and the Grants with get_shop.
# Part 2 (stages 14-21) grants one test Caller every Tool and another only
# the Read tools, calls every Tool, takes one inventory item through a Dry
# run, a real write, a retry and a stale write, puts it back, does the same
# for a move to damaged and back, runs one test Caller out of its Quota while
# the other keeps working, and checks the Audit records.

ISSUE=9          # the smoke-test issue the results are posted to
CAP="github.com/nathan-scheele/storewarden"
ADMIN="https://login.tailscale.com/admin"
RESULTS=()       # "PASS  check" or "FAIL  check"
SW_PID=""        # storewarden
SMOKE_PID=""     # storewarden-smoke, the test Caller; fds 3 (its stdin) and 4 (its stdout)
RO_PID=""        # storewarden-smoke, the read-only test Caller; fds 5 and 6
AUDIT=""         # storewarden's Audit records
HELLO=""         # a test Caller's first line: the tailnet it joined
SCENARIO='{}'    # the last Part 2 command's JSON result
LOG=""           # storewarden's JSON log lines
SMOKE_LOG=""     # storewarden-smoke's stderr
SMOKE='{}'       # the last check's JSON result
SEEN=""          # what the last check saw, in words
MARK=0           # storewarden's log line count when the current check started
OPENED_URL=""    # the last tsnet login URL shown
APP_TAILNET=""   # the Tailscale app's tailnet, never to be used

# record PASS|FAIL "check" notes one check's outcome for the results table.
record() {
  RESULTS+=("$1  $2")
  if [[ "$1" == PASS ]]; then printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else warn "FAIL: $2"; fi
}

# visit URL prints a URL to open in the personal browser window. It never
# opens the default browser, which may be signed into another Tailscale account.
visit() { printf '  %s↗ open in your personal window:%s %s\n' "$GREEN" "$RESET" "$1"; }

# cleanup stops every process if the wizard exits early. Closing a test
# Caller's stdin makes it remove its node and exit.
cleanup() {
  if [[ -n "$SMOKE_PID" ]]; then
    exec 3>&- || true
    wait "$SMOKE_PID" 2>/dev/null || true
  fi
  if [[ -n "$RO_PID" ]]; then
    exec 5>&- || true
    wait "$RO_PID" 2>/dev/null || true
  fi
  if [[ -n "$SW_PID" ]] && kill -0 "$SW_PID" 2>/dev/null; then
    kill -INT "$SW_PID" 2>/dev/null || true
    wait "$SW_PID" 2>/dev/null || true
  fi
}

# json_get JSON PATH prints a field of a JSON object; PATH is dotted, and a
# list prints comma-separated.
json_get() {
  python3 -c '
import json, sys
try:
    v = json.loads(sys.argv[1])
except ValueError:
    sys.exit(0)
for k in sys.argv[2].split("."):
    v = v.get(k) if isinstance(v, dict) else None
if isinstance(v, list):
    v = ",".join(map(str, v))
elif isinstance(v, dict):
    v = json.dumps(v)
print("" if v is None else v)
' "$1" "$2"
}

log_lines() { wc -l < "$LOG" | tr -d ' '; }

# logged FROM LEVEL TEXT succeeds if a storewarden log line after line FROM
# is at LEVEL and contains TEXT.
logged() {
  tail -n +"$(( $1 + 1 ))" "$LOG" | python3 -c '
import json, sys
for line in sys.stdin:
    try:
        entry = json.loads(line)
    except ValueError:
        continue
    if entry.get("level") == sys.argv[1] and sys.argv[2] in line:
        sys.exit(0)
sys.exit(1)
' "$2" "$3"
}

# show_login_url FILE prints a tsnet login URL from FILE, once. tsnet asks
# for one when an auth key is missing or rejected.
show_login_url() {
  local url
  url=$(grep -o 'https://login.tailscale.com/a/[A-Za-z0-9]*' "$1" | tail -n 1 || true)
  if [[ -n "$url" && "$url" != "$OPENED_URL" ]]; then
    warn "tsnet is asking for a login, so the auth key didn't work."
    visit "$url"
    note "Approve it only if that window is your personal account."
    OPENED_URL="$url"
  fi
}

# require_tailnet NAME WHO stops the wizard if WHO joined the Tailscale app's tailnet.
require_tailnet() {
  if [[ -n "$APP_TAILNET" && "$1" == "$APP_TAILNET" ]]; then
    warn "$2 joined the tailnet the Tailscale app is logged into. Stopping."
    note "Remove '$2' from that tailnet's Machines page, and make the auth keys"
    note "again from your personal account."
    [[ "$2" == storewarden ]] && note "Then delete \"$STATE_DIR\" so the next run registers afresh."
    exit 1
  fi
}

# smoke_check asks the test Caller to call storewarden once; sets SMOKE.
smoke_check() {
  printf 'check\n' >&3
  if ! read -r -t 60 SMOKE <&4; then SMOKE='{}'; fi
  if [[ -n "$(smoke_get error)" ]]; then SEEN="error: $(smoke_get error)"
  else SEEN="healthz $(smoke_get healthz), MCP HTTP $(smoke_get mcp), tools [$(smoke_get tools)]"; fi
}
smoke_get() { json_get "$SMOKE" "$1"; }

# poll SECONDS CHECK runs CHECK every 3 s until it succeeds, showing what the
# last check saw. When time runs out it asks whether to keep waiting. Policy
# edits usually reach the storewarden node within seconds.
poll() {
  local deadline
  while true; do
    deadline=$(( SECONDS + $1 ))
    while (( SECONDS < deadline )); do
      if "$2"; then printf '\r\033[K'; return 0; fi
      printf '\r\033[K  %swaiting %ss · seen: %s%s' "$DIM" "$(( deadline - SECONDS ))" "$SEEN" "$RESET"
      sleep 3
    done
    printf '\n'
    warn "Not there yet. Last seen: $SEEN"
    confirm "Keep waiting another $1 s?" || return 1
  done
}

# await_caller PID FD LOGFILE waits for a test Caller to join the tailnet and
# sets HELLO to its first line. It stops the wizard if the Caller exits or
# takes too long.
await_caller() {
  local deadline=$(( SECONDS + 180 ))
  until read -r -t 2 -u "$2" HELLO; do
    if ! kill -0 "$1" 2>/dev/null; then
      warn "The test Caller exited. The end of its log:"
      tail -n 20 "$3"
      exit 1
    fi
    show_login_url "$3"
    if (( SECONDS >= deadline )); then
      warn "Timed out. The end of its log:"
      tail -n 20 "$3"
      exit 1
    fi
  done
}

# run_scenario CMD IN OUT sends a Part 2 command to a test Caller and sets
# SCENARIO to its answer.
run_scenario() {
  printf '%s\n' "$1" >&"$2"
  if ! read -r -t 300 -u "$3" SCENARIO; then SCENARIO='{}'; fi
}

# record_scenario records each check in SCENARIO, with what it saw, and a
# FAIL if the command stopped early. Only failures put what was seen in the
# results table, which may be posted to the public issue.
record_scenario() {
  local verdict check detail
  while IFS=$'\t' read -r verdict check detail; do
    if [[ "$verdict" == PASS ]]; then
      record PASS "$check"
      [[ -n "$detail" ]] && note "    $detail"
    else
      record FAIL "$check${detail:+ ($detail)}"
    fi
  done < <(python3 -c '
import json, sys
try:
    s = json.loads(sys.argv[1])
except ValueError:
    s = {"error": "no answer from the test Caller"}
for step in s.get("steps") or []:
    detail = (step.get("detail") or "").replace("\t", " ")
    print("PASS" if step.get("pass") else "FAIL", step["check"], detail, sep="\t")
if s.get("error"):
    print("FAIL", "the checks ran to the end", s["error"], sep="\t")
' "$SCENARIO")
}
scenario_get() { json_get "$SCENARIO" "$1"; }

# check_audit FILE EXECUTED MOVED SHOP TITLE checks the Audit records in
# FILE: their fields, an attempt and a result for each Tool, the denials,
# the Quota refusals, the Dry run flag and Idempotency key of the real write
# (its request ID is EXECUTED) and of the real move (MOVED), and that no
# record holds Shopify response content (the shop name and product title
# that Shopify returned). It prints one "PASS|FAIL<tab>check<tab>detail"
# line per check.
check_audit() {
  python3 -c '
import json, sys

path, executed, moved, shop, title = sys.argv[1:6]
fields = ["time", "request_id", "phase", "caller", "tool", "args", "decision",
          "reason", "dry_run", "idempotency_key", "outcome", "error", "duration_ms"]
caller_fields = ["node_id", "node_name", "tags", "user"]
tools = ["get_shop", "search_products", "get_product", "get_inventory", "set_inventory_quantity",
         "move_inventory_quantity"]

def report(ok, check, detail=""):
    print("PASS" if ok else "FAIL", check, detail, sep="\t")

text = open(path).read()
records, unparsable = [], 0
for line in text.splitlines():
    try:
        records.append(json.loads(line))
    except ValueError:
        unparsable += 1
incomplete = [r for r in records
              if any(f not in r for f in fields)
              or any(f not in (r.get("caller") or {}) for f in caller_fields)]
report(records and not unparsable and not incomplete,
       "every Audit record is JSON with every documented field",
       f"{len(records)} records, {unparsable} not JSON, {len(incomplete)} missing fields")

seen = {(r.get("tool"), r.get("phase")) for r in records}
lacking = [t for t in tools if (t, "attempt") not in seen or (t, "result") not in seen]
report(not lacking, "every Tool called has attempt and result records",
       "missing: " + ", ".join(lacking) if lacking else "")

denied = [r for r in records if r.get("phase") == "denied"]
report(any(r.get("tool") == "" for r in denied)
       and any(r.get("tool") == "set_inventory_quantity" for r in denied)
       and any(r.get("tool") == "move_inventory_quantity" for r in denied),
       "the 403s and the read-only Caller'"'"'s Write tool calls have denial records",
       f"{len(denied)} denial records")

refused = [r for r in records if r.get("phase") == "result" and "Quota" in (r.get("error") or "")]
attempts = {r.get("request_id") for r in records if r.get("phase") == "attempt"}
report(refused and all(r.get("request_id") in attempts for r in refused)
       and not any(r.get("tool") == "get_inventory" for r in denied),
       "a Quota refusal has an attempt record, a result record naming the Quota, and no denial record",
       f"{len(refused)} Quota refusals")

# A real move'"'"'s args must also hold both Inventory states, the quantity and
# both Expected quantities.
for request_id, what, args in ((executed, "real write", []),
                               (moved, "real move", ["from", "to", "quantity", "expected_from_quantity",
                                                     "expected_to_quantity"])):
    write = [r for r in records if r.get("request_id") == request_id]
    result = [r for r in write if r.get("phase") == "result"]
    report(request_id and len(write) == 2
           and all(r.get("dry_run") is False and r.get("idempotency_key")
                   and all(a in (r.get("args") or {}) for a in args) for r in write)
           and result and (result[0].get("shopify") or {}).get("request_id"),
           f"the {what}'"'"'s records show dry_run false, its Idempotency key and Shopify'"'"'s request ID"
           + (", with both states, the quantity and both Expected quantities" if args else ""),
           f"{len(write)} records")

leaked = [name for name, value in (("shop name", shop), ("product title", title))
          if value and value in text]
report(not leaked, "no Audit record holds Shopify response content",
       "found the " + " and the ".join(leaked) if leaked else "")
' "$@"
}

check_all_granted() {
  smoke_check
  local tools; tools=$(smoke_get tools)
  [[ "$(smoke_get mcp)" == 200 && ",$tools," == *",set_inventory_quantity,"* &&
     ",$tools," == *",move_inventory_quantity,"* && $(tr -cd , <<<"$tools" | wc -c) -eq 5 ]]
}

check_healthy()     { smoke_check; [[ "$(smoke_get healthz)" == 200 && "$(smoke_get healthz_body)" == healthy ]]; }
check_granted() {
  smoke_check
  [[ "$(smoke_get mcp)" == 200 && "$(smoke_get tools)" == get_shop &&
     "$(smoke_get get_shop.myshopify_domain)" == "$SHOPIFY_STORE" ]]
}
check_warned()      { check_granted && logged "$MARK" WARN delete_everything; }
check_typo_denied() { smoke_check; [[ "$(smoke_get mcp)" == 403 ]] && logged "$MARK" ERROR "unknown field"; }
check_no_cap()      { smoke_check; [[ "$(smoke_get mcp)" == 403 ]] && logged "$MARK" INFO "no $CAP capability"; }

# policy_file VALUE [RO_VALUE] prints a whole policy file for the personal
# tailnet, with VALUE as the test Caller's storewarden capability value. With
# no VALUE, its grant has no app capability at all. With RO_VALUE, the
# read-only test Caller gets a grant with that value too.
policy_file() {
  local app="" ro=""
  if [[ -n "${1:-}" ]]; then
    app=$(printf ',\n      "app": {\n        "%s": [%s]\n      }' "$CAP" "$1")
  fi
  if [[ -n "${2:-}" ]]; then
    ro=$(printf '\n    // The read-only test Caller may use the Tools named here.\n    {\n      "src": ["tag:storewarden-smoke-ro"],\n      "dst": ["tag:storewarden"],\n      "ip":  ["tcp:80"],\n      "app": {\n        "%s": [%s]\n      }\n    },' "$CAP" "$2")
  fi
  cat <<EOF
// storewarden smoke test (scripts/smoke-tailnet.sh).
// This is the whole policy file: paste it over everything that's there.
{
  "tagOwners": {
    "tag:storewarden":       ["autogroup:admin"],
    "tag:storewarden-smoke": ["autogroup:admin"],
    "tag:storewarden-smoke-ro": ["autogroup:admin"],
  },
  "grants": [
    // Tailscale's default: every device can reach every other device.
    {"src": ["*"], "dst": ["*"], "ip": ["*"]},
    // The test Caller may reach storewarden on port 80, and use its Tools.
    {
      "src": ["tag:storewarden-smoke"],
      "dst": ["tag:storewarden"],
      "ip":  ["tcp:80"]$app
    },$ro
  ],
}
EOF
}

# show_policy [VALUE [RO_VALUE]] prints the whole policy file and copies it
# to the clipboard, where there is one.
show_policy() {
  local policy
  policy=$(policy_file "${1:-}" "${2:-}")
  printf '\n%s%s%s\n\n' "$BOLD" "$policy" "$RESET"
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s\n' "$policy" | pbcopy
    printf '  %s✓ copied to your clipboard%s\n' "$GREEN" "$RESET"
  fi
}

# edit_policy WHAT [VALUE [RO_VALUE]] walks through replacing the policy file.
edit_policy() {
  visit "$ADMIN/acls/file"
  step "$1"
  step "Select everything in the policy file, paste this over it, then Save:"
  show_policy "${2:-}" "${3:-}"
  pause "Saved? Press Enter"
}

run_wizard() {

TOTAL_STAGES=23

cd "$(dirname "${BASH_SOURCE[0]}")/.."
# A worktree has no .env of its own, so use the main checkout's.
if [[ ! -f "$ENV_FILE" ]]; then
  ENV_FILE="$(dirname "$(git rev-parse --path-format=absolute --git-common-dir)")/.env"
fi
trap cleanup EXIT
case "$(uname)" in
  Darwin) STATE_DIR="${STATE_DIR:-$HOME/Library/Application Support/storewarden}" ;;
  *)      STATE_DIR="${STATE_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/storewarden}" ;;
esac

banner "storewarden smoke test (#$ISSUE): the tailnet, every Tool, the Write tools and Quotas"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
local missing=0 cmd
for cmd in go python3 lsof mkfifo; do
  command -v "$cmd" >/dev/null 2>&1 || { warn "missing: $cmd"; missing=1; }
done
SHOPIFY_STORE=$(_existing SHOPIFY_STORE || true)
SHOPIFY_CLIENT_ID=$(_existing SHOPIFY_CLIENT_ID || true)
SHOPIFY_CLIENT_SECRET=$(_existing SHOPIFY_CLIENT_SECRET || true)
if [[ -z "$SHOPIFY_STORE" || -z "$SHOPIFY_CLIENT_ID" || -z "$SHOPIFY_CLIENT_SECRET" ]]; then
  warn "SHOPIFY_STORE, SHOPIFY_CLIENT_ID and SHOPIFY_CLIENT_SECRET must be in $ENV_FILE."
  note "Run scripts/setup-shopify.sh first."
  missing=1
fi
(( missing )) && exit 1
APP_TAILNET=$(tailscale status --json 2>/dev/null | python3 -c '
import json, sys
print((json.load(sys.stdin).get("CurrentTailnet") or {}).get("Name", ""))
' 2>/dev/null || true)
say "Store: $SHOPIFY_STORE"
say "Everything runs in your personal tailnet. The Tailscale app on this"
say "machine isn't used."
if [[ -n "$APP_TAILNET" ]]; then
  note "The wizard stops if anything joins the tailnet the Tailscale app is logged into."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Personal Tailscale account"
step "Open a private window, or a browser profile, signed into your personal"
step "Tailscale account. Create one at https://login.tailscale.com/start if needed."
step "Check the tailnet name at the top of the admin console: it must not be the one the Tailscale app uses."
note "From here on the wizard prints URLs for that window instead of opening your"
note "default browser."
pause "In your personal admin console? Press Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Grant get_shop in the personal tailnet policy"
warn "This replaces your personal tailnet's whole policy file. If it has rules"
warn "you want to keep, copy them somewhere first."
note "The test Caller's grant needs both parts: ip lets traffic reach port 80,"
note "and app grants the Tool."
edit_policy "Grant the test Caller get_shop." '{"tools": ["get_shop"]}'

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Auth key for the storewarden node"
TS_AUTHKEY=""
if [[ -f "$STATE_DIR/tailscaled.state" ]]; then
  say "The storewarden node is already registered (state found), so no key is needed."
else
  visit "$ADMIN/settings/keys"
  step "Generate auth key… → Tags: tag:storewarden."
  step "Leave Ephemeral off. Reusable isn't needed."
  ask_secret TS_AUTHKEY "Paste the auth key (tskey-auth-…):"
  note "It's used once to register the node and isn't saved."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Auth key for the test Caller"
say "The test Caller is a separate, ephemeral node that calls storewarden with"
say "the official MCP SDK client. Each run is a new node, so its key is reusable"
say "and is saved in $ENV_FILE (gitignored)."
if [[ -z "$(_existing TS_SMOKE_AUTHKEY || true)" ]]; then
  visit "$ADMIN/settings/keys"
  step "Generate auth key… → Reusable on, Ephemeral on, Tags: tag:storewarden-smoke."
fi
ask_secret TS_SMOKE_AUTHKEY "Paste the auth key (tskey-auth-…):"
write_env TS_SMOKE_AUTHKEY "$TS_SMOKE_AUTHKEY"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Auth key for the read-only test Caller"
say "Part 2 adds a second test Caller, granted only the Read tools, to check"
say "that the Write tools are hidden from it. It needs its own tag, so its own key,"
say "saved in $ENV_FILE as well."
if [[ -z "$(_existing TS_SMOKE_RO_AUTHKEY || true)" ]]; then
  visit "$ADMIN/settings/keys"
  step "Generate auth key… → Reusable on, Ephemeral on, Tags: tag:storewarden-smoke-ro."
  note "The tag exists once the policy from stage 3 is saved."
fi
ask_secret TS_SMOKE_RO_AUTHKEY "Paste the auth key (tskey-auth-…):"
write_env TS_SMOKE_RO_AUTHKEY "$TS_SMOKE_RO_AUTHKEY"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Start storewarden"
local tmpdir
tmpdir=$(mktemp -d)
LOG="$tmpdir/storewarden.log"
SMOKE_LOG="$tmpdir/storewarden-smoke.log"
AUDIT="$tmpdir/audit.jsonl"
say "Building storewarden and the test Caller…"
make build BIN="$tmpdir"
# Secrets reach the processes through their environment, never their arguments.
(
  export SHOPIFY_CLIENT_ID SHOPIFY_CLIENT_SECRET
  if [[ -n "$TS_AUTHKEY" ]]; then export TS_AUTHKEY; fi
  # A Quota of 5%: on the dev store's Plus plan, 1000 points refilling at
  # 50 a second. That covers Part 2, and a burst of calls spends it.
  exec "$tmpdir/storewarden" --store "$SHOPIFY_STORE" --state-dir "$STATE_DIR" \
    --allow-writes --quota-share 0.05 --audit-log "$AUDIT"
) >"$LOG" 2>&1 &
SW_PID=$!
say "Waiting for it to join the tailnet…"
local deadline=$(( SECONDS + 180 ))
until logged 0 INFO "serving MCP"; do
  if ! kill -0 "$SW_PID" 2>/dev/null; then
    SW_PID=""
    warn "storewarden exited. The end of its log:"
    tail -n 20 "$LOG"
    exit 1
  fi
  show_login_url "$LOG"
  if (( SECONDS >= deadline )); then
    warn "Timed out. The end of its log:"
    tail -n 20 "$LOG"
    exit 1
  fi
  sleep 2
done
local serving sw_tailnet ip
serving=$(grep '"msg":"serving MCP"' "$LOG" | head -n 1)
sw_tailnet=$(json_get "$serving" tailnet)
require_tailnet "$sw_tailnet" storewarden
ip=$(json_get "$serving" tailscale_ips)
ip=${ip%%,*} # the IPv4 address comes first
say "storewarden joined \"$sw_tailnet\" at $ip."
if ! confirm "Is \"$sw_tailnet\" your personal tailnet?"; then
  warn "Stopping. Remove 'storewarden' from that tailnet's Machines page."
  note "Then delete \"$STATE_DIR\" and run the wizard again."
  exit 1
fi
record PASS "storewarden joined the personal tailnet and is serving"
note "Logs: $LOG"
note "Audit records: $AUDIT"
note "It runs in Write mode, but only the Grant in Part 2 names the Write tools."
step "Optional: on the Machines page, 'storewarden' shows tag:storewarden and no Ephemeral badge."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Start the test Caller"
mkfifo "$tmpdir/smoke.in" "$tmpdir/smoke.out"
(
  TS_AUTHKEY="$TS_SMOKE_AUTHKEY"
  export TS_AUTHKEY
  exec "$tmpdir/storewarden-smoke" --target "$ip"
) <"$tmpdir/smoke.in" >"$tmpdir/smoke.out" 2>"$SMOKE_LOG" &
SMOKE_PID=$!
exec 3>"$tmpdir/smoke.in"
exec 4<"$tmpdir/smoke.out"
say "Waiting for it to join the tailnet…"
local smoke_tailnet
await_caller "$SMOKE_PID" 4 "$SMOKE_LOG"
smoke_tailnet=$(json_get "$HELLO" tailnet)
require_tailnet "$smoke_tailnet" storewarden-smoke
if [[ "$smoke_tailnet" != "$sw_tailnet" ]]; then
  warn "The test Caller joined \"$smoke_tailnet\", not \"$sw_tailnet\". Stopping."
  note "Make its auth key in the same personal tailnet as storewarden's."
  exit 1
fi
record PASS "the test Caller joined the same tailnet as storewarden"
note "Logs: $SMOKE_LOG"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Call get_shop over the tailnet"
say "The first connection between the nodes can take a few seconds."
if poll 60 check_healthy; then record PASS "/healthz says healthy"
else record FAIL "/healthz says healthy ($(smoke_get error))"; fi
smoke_check
if [[ "$(smoke_get mcp)" == 200 && "$(smoke_get tools)" == get_shop ]]; then
  record PASS "tools/list shows only get_shop"
else
  record FAIL "tools/list shows only get_shop (HTTP $(smoke_get mcp), tools: $(smoke_get tools))"
fi
if [[ "$(smoke_get get_shop.myshopify_domain)" == "$SHOPIFY_STORE" ]]; then
  record PASS "get_shop returns the dev store"
  say "name=$(smoke_get get_shop.name)  plan=$(smoke_get get_shop.plan)  currency=$(smoke_get get_shop.currency)"
  say "throttle_status=$(smoke_get get_shop.throttle_status)"
else
  record FAIL "get_shop returns the dev store ($(smoke_get error))"
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Tailnet only"
local listeners
listeners=$(lsof -nP -a -p "$SW_PID" -iTCP -sTCP:LISTEN 2>/dev/null || true)
if [[ -z "$listeners" ]]; then
  record PASS "no TCP listener on the host"
else
  record FAIL "storewarden has a TCP listener on the host"
  printf '%s\n' "$listeners"
fi
note "Port 80 exists only inside tsnet, on the tailnet address."
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Unknown Tool → warning"
MARK=$(log_lines)
edit_policy "Add a Tool storewarden doesn't have (delete_everything)." '{"tools": ["get_shop", "delete_everything"]}'
if poll 120 check_warned; then record PASS "unknown Tool name logs a warning; get_shop still granted"
else record FAIL "unknown Tool name logs a warning; get_shop still granted"; fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Typo → deny"
MARK=$(log_lines)
edit_policy "Make a typo: \"tool\" instead of \"tools\"." '{"tool": ["get_shop"]}'
if poll 120 check_typo_denied; then record PASS "unknown field in a Grant → 403 and an ERROR log"
else record FAIL "unknown field in a Grant → 403 and an ERROR log"; fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "No Grant → 403"
MARK=$(log_lines)
edit_policy "Take away the app capability; the grant keeps only ip."
if poll 120 check_no_cap; then record PASS "no capability → 403"
else record FAIL "no capability → 403"; fi
if check_healthy; then record PASS "/healthz works without a capability"
else record FAIL "/healthz works without a capability"; fi
edit_policy "Put get_shop back." '{"tools": ["get_shop"]}'
if poll 120 check_granted; then record PASS "get_shop granted again"
else record FAIL "get_shop granted again"; fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Part 2: grant every Tool"
say "Part 1 is done. Part 2 grants the test Caller all six Tools, and a second,"
say "read-only test Caller only the four Read tools."
edit_policy "Grant every Tool to the test Caller, and the Read tools to the read-only one." \
  '{"tools": ["get_shop", "search_products", "get_product", "get_inventory", "set_inventory_quantity", "move_inventory_quantity"]}' \
  '{"tools": ["get_shop", "search_products", "get_product", "get_inventory"]}'
if poll 120 check_all_granted; then record PASS "with Write mode on, a Grant naming all six Tools shows all six"
else record FAIL "with Write mode on, a Grant naming all six Tools shows all six (tools: $(smoke_get tools))"; fi
say "Starting the read-only test Caller…"
local ro_log="$tmpdir/storewarden-smoke-ro.log"
mkfifo "$tmpdir/ro.in" "$tmpdir/ro.out"
(
  TS_AUTHKEY="$TS_SMOKE_RO_AUTHKEY"
  export TS_AUTHKEY
  exec "$tmpdir/storewarden-smoke" --target "$ip" \
    --hostname storewarden-smoke-ro --tags tag:storewarden-smoke-ro
) <"$tmpdir/ro.in" >"$tmpdir/ro.out" 2>"$ro_log" &
RO_PID=$!
exec 5>"$tmpdir/ro.in"
exec 6<"$tmpdir/ro.out"
await_caller "$RO_PID" 6 "$ro_log"
local ro_tailnet
ro_tailnet=$(json_get "$HELLO" tailnet)
require_tailnet "$ro_tailnet" storewarden-smoke-ro
if [[ "$ro_tailnet" != "$sw_tailnet" ]]; then
  warn "The read-only test Caller joined a different tailnet. Stopping."
  note "Make its auth key in the same personal tailnet as storewarden's."
  exit 1
fi
record PASS "the read-only test Caller joined the same tailnet"
pause

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Every Tool, and the Write tool from Dry run to retry"
say "The test Caller now calls each Read tool, then picks the first stocked"
say "inventory item and, on the development store:"
step "makes a Dry run of adding 1 to its available quantity;"
step "makes the change for real, with an Idempotency key and Expected quantity;"
step "retries that call with the same key, which must not add 1 again;"
step "tries another change with the old Expected quantity, which must be refused;"
step "puts the quantity back."
pause "Press Enter to run it (it takes a few seconds)"
run_scenario tools 3 4
record_scenario
local shop_name product_title executed_id restored_id product_id variant_id item_id location_id
shop_name=$(scenario_get shop_name)
product_title=$(scenario_get product_title)
executed_id=$(scenario_get executed_request_id)
restored_id=$(scenario_get restored_request_id)
product_id=$(scenario_get product_id)
variant_id=$(scenario_get variant_id)
item_id=$(scenario_get item_id)
location_id=$(scenario_get location_id)
if [[ -n "$product_title" ]]; then
  note "Item: $product_title, $item_id at $location_id;"
  note "available was $(scenario_get before)."
fi
pause

# ── 16 ────────────────────────────────────────────────────────────────────
stage "move_inventory_quantity from Dry run to moving back"
local moved_id moved_back_id
if [[ -n "$item_id" ]]; then
  say "On the same inventory item and location, the test Caller now:"
  step "makes a Dry run of moving 1 unit from available to damaged;"
  step "makes the move for real, with an Idempotency key and both Expected quantities;"
  step "retries that call with the same key, which must not move again, and records"
  step "which answer came back;"
  step "tries another move with the old Expected quantities, which must be refused;"
  step "asks to move more than damaged holds with the real Expected quantities,"
  step "which storewarden must refuse;"
  step "asks again claiming damaged holds enough, which Shopify must refuse as stale;"
  step "moves the unit back to available."
  pause "Press Enter to run it (it takes a few seconds)"
  run_scenario "move $item_id $location_id" 3 4
  record_scenario
  moved_id=$(scenario_get executed_request_id)
  moved_back_id=$(scenario_get restored_request_id)
else
  warn "The previous stage found no stocked inventory item to move."
  record FAIL "the move round trip ran (no stocked inventory item)"
fi
pause

# ── 17 ────────────────────────────────────────────────────────────────────
stage "The change and the move in Shopify's inventory history"
if [[ -n "$executed_id" || -n "$moved_id" ]]; then
  local handle product variant
  handle=${SHOPIFY_STORE%.myshopify.com}
  product=${product_id##*/}
  variant=${variant_id##*/}
  say "Open this in the browser where you're signed into the development store's"
  say "admin, then open the variant's inventory adjustment history:"
  printf '  %s↗%s https://admin.shopify.com/store/%s/products/%s/variants/%s\n' \
    "$GREEN" "$RESET" "$handle" "$product" "$variant"
  say "Look for these entries and their references:"
  [[ -n "$executed_id" ]] && note "  storewarden://audit/$executed_id   (+1, reason correction)"
  [[ -n "$restored_id" ]] && note "  storewarden://audit/$restored_id   (put back)"
  [[ -n "$moved_id" ]] && note "  storewarden://audit/$moved_id   (1 available → damaged, reason damaged)"
  [[ -n "$moved_back_id" ]] && note "  storewarden://audit/$moved_back_id   (1 damaged → available, reason damaged)"
fi
if [[ -n "$executed_id" ]]; then
  if confirm "Does the history show the change with its storewarden:// reference?"; then
    record PASS "the change shows in Shopify's inventory history with its storewarden:// reference (checked by hand)"
  else
    record FAIL "the change shows in Shopify's inventory history with its storewarden:// reference (checked by hand)"
  fi
else
  warn "There was no real write to look for."
  record FAIL "the change shows in Shopify's inventory history (no real write was made)"
fi
if [[ -n "$moved_id" ]]; then
  if confirm "Does the history show the move to damaged with reason damaged and its storewarden:// reference?"; then
    record PASS "the move shows in Shopify's inventory history with its reason and storewarden:// reference (checked by hand)"
  else
    record FAIL "the move shows in Shopify's inventory history with its reason and storewarden:// reference (checked by hand)"
  fi
else
  warn "There was no real move to look for."
  record FAIL "the move shows in Shopify's inventory history (no real move was made)"
fi
pause

# ── 18 ────────────────────────────────────────────────────────────────────
stage "The read-only test Caller"
run_scenario read-only 5 6
record_scenario
pause

# ── 19 ────────────────────────────────────────────────────────────────────
stage "One Caller runs out of its Quota"
say "storewarden runs with --quota-share 0.05, so each Caller's Quota is 5% of"
say "the Store's rate limit. The test Caller now calls get_inventory, several"
say "calls at once, until storewarden refuses it for its Quota. Straight after,"
say "the read-only test Caller makes the same call, which must still work."
if [[ -n "$item_id" ]]; then
  pause "Press Enter to run it (it takes a few seconds)"
  run_scenario "quota $item_id" 3 4
  record_scenario
  run_scenario "quota-other $item_id" 5 6
  record_scenario
else
  warn "Part 2 found no inventory item to call get_inventory with."
  record FAIL "one Caller runs out of its Quota while another keeps working (no inventory item)"
fi
pause

# ── 20 ────────────────────────────────────────────────────────────────────
stage "Clean shutdown"
MARK=$(log_lines)
say "Sending SIGINT to storewarden…"
local rc=0
kill -INT "$SW_PID"
wait "$SW_PID" || rc=$?
SW_PID=""
if (( rc == 0 )) && logged "$MARK" INFO "shutting down"; then
  record PASS "SIGINT shuts down cleanly (exit 0)"
else
  record FAIL "SIGINT shuts down cleanly (exit $rc)"
fi
pause

# ── 21 ────────────────────────────────────────────────────────────────────
stage "Audit records"
say "Reading $AUDIT, now that storewarden has flushed and closed it."
local verdict check detail
while IFS=$'\t' read -r verdict check detail; do
  if [[ "$verdict" == PASS ]]; then
    record PASS "$check"
    [[ -n "$detail" ]] && note "    $detail"
  else
    record FAIL "$check${detail:+ ($detail)}"
  fi
done < <(check_audit "$AUDIT" "$executed_id" "$moved_id" "$shop_name" "$product_title")
pause

# ── 22 ────────────────────────────────────────────────────────────────────
stage "Tidy up"
say "Stopping the test Callers; each removes its own node from the tailnet."
exec 3>&- 5>&-
wait "$SMOKE_PID" || true
wait "$RO_PID" || true
SMOKE_PID="" RO_PID=""
say "Left in place, for the next run:"
note "  - the 'storewarden' node, and its state in \"$STATE_DIR\""
note "  - the tags and grants in the policy file"
note "  - the test Callers' keys, as TS_SMOKE_AUTHKEY and TS_SMOKE_RO_AUTHKEY in $ENV_FILE"
say "To remove them: Machines → storewarden → Remove; delete the policy lines;"
say "revoke the keys under Settings → Keys and delete them from $ENV_FILE."
pause

# ── 23 ────────────────────────────────────────────────────────────────────
stage "Results"
local r passed=0 failed=0 table=""
for r in "${RESULTS[@]}"; do
  printf '  %s\n' "$r"
  if [[ "$r" == PASS* ]]; then passed=$(( passed + 1 )); else failed=$(( failed + 1 )); fi
  table+="| ${r%%  *} | ${r#*  } |"$'\n'
done
printf '\n'
say "$passed passed, $failed failed."
note "Logs: $LOG"
printf '\n'
# The comment names no tailnet, node or address: the repo is public.
if confirm "Post this table as a comment on issue #$ISSUE?"; then
  local body
  body="Manual smoke test with \`scripts/smoke-tailnet.sh\` at $(git rev-parse --short HEAD), against the development store: $passed passed, $failed failed."$'\n\n'
  body+="| Result | Check |"$'\n'"|---|---|"$'\n'"$table"$'\n'
  body+="The calls were made by \`cmd/storewarden-smoke\`, two separate ephemeral tailnet nodes, with the official MCP SDK client. The inventory history was checked by hand in the Shopify admin. Not covered: capturing a live throttled response."
  if gh issue comment "$ISSUE" -R nathan-scheele/storewarden --body "$body" >/dev/null; then
    printf '  %s✓ posted%s to issue #%s\n' "$GREEN" "$RESET" "$ISSUE"
  else
    SKIPPED+=("posting the results to issue #$ISSUE")
  fi
fi

finish
}

run_wizard "$@"; exit
